const kitBedMap = {
  "1":  "CES_v3_hg38_original_normalized_chr.bed",
  "40": "Twist_Exome_hg38_original_normalized_chr.bed",
  "73": "HCS_v2_0_1_hg38_target_normalized.bed",
  "97": "Twist_Exome_hg38_original_with_mtDNA_normalized_chr.bed"
};
// Claim returns [{success:true}] when 0 rows claimed -> drop it so worker stops cleanly
const items = $("Claim All Pending").all().filter(it => it.json.read_ref != null);
return items.map((item, idx) => ({
  json: { ...item.json, bed_file_path: kitBedMap[String(item.json.kit_ref)] || "" },
  pairedItem: { item: idx }
}));

