parameters.jsCode:
const metrics = JSON.parse($input.item.json.stdout);
const data_op_ref = metrics.data_op_ref;

// data_op_ref hariç tüm parametreleri al
const excludeKeys = ['data_op_ref'];
const result = [];

for (const [key, value] of Object.entries(metrics)) {
  if (!excludeKeys.includes(key)) {
    result.push({
      data_op_ref: data_op_ref,
      parameter: key,
      value: value
    });
  }
}

return result.map(item => ({ json: item }));

